sys_ux_client_script.script:
function handler({api, event, helpers, imports}) {

    const intervalId = api.state.intervalId;

    // Stop the running timer
    if (intervalId !== -1) {
        helpers.timing.clearInterval(intervalId);
    }

    // Reset stopwatch display
    api.setState('elapsedTime', '00:00:00.000');

    // Reset timer state
    api.setState('intervalId', -1);
    api.setState('isRunning', false);
    api.setState('isPaused', false);

    // Clear all recorded laps
    api.setState('lapTimes', []);
}
